// Curated course records. Equations are compact teaching summaries; source
// slides retain protonation, stereochemistry and complete reaction details.
const courseReactions = [];
function courseReaction(id,name,equation,metabolites,chapter,page,objects=[],regulation=[]){
 courseReactions.push({id,name,equation,metabolites,source:[chapter,page],objects,regulation});
}
